cd /tmp && mkdir -p pico_explore && cd pico_explore && cat > explore.py <<'EOF'
q = ['Mut','Imm','RDM','RO','Lost','Bot']
qf = ['Mut_f','Imm_f','RDM_f','RO_f']
qr = ['Imm_r','Mut_r']

def vpa_qq_abstract(q1,q2):
    if q1=='RO' and q2=='RDM': return 'Lost'
    if q2=='RDM': return q1
    return q2

def vpa_qq_readonly(q1,q2):
    if q1=='RO' and q2=='RDM': return 'Lost'
    if q2=='RDM': return q1
    if q1=='Mut' and q2=='Mut': return 'Mut'
    if q2=='Mut': return 'Lost'
    return q2

def stype_fld_ro(q1,q2):
    if q1=='RO' and q2=='RDM_f': return 'Lost'
    if q2=='RDM_f': return q1
    if q2=='Imm_f': return 'Imm'
    if q1=='Mut' and q2=='Mut_f': return 'Mut'
    if q2=='Mut_f': return 'Lost'
    if q2=='RO_f': return 'RO'
    raise Exception

def rec_fld(q1,q2):
    if q1=='Imm_r' and q2=='RDM_f': return 'Imm'
    if q1=='Mut_r' and q2=='RDM_f': return 'Mut'
    if q2=='Imm_f': return 'Imm'
    if q2=='Mut_f': return 'Mut'
    if q2=='RO_f': return 'RO'
    raise Exception

def vpa_runtime(q1,q2):
    if q1=='Imm_r' and q2=='RDM': return 'Imm'
    if q1=='Mut_r' and q2=='RDM': return 'Mut'
    return q2

def qctx_typable_context(qr_,qs,qcontext):
    r = vpa_runtime(qcontext,qs)
    if qr_=='Imm_r':
        return r in ['Imm','RO','Lost']
    else:
        return r in ['Mut','RO','Lost']

def qctx_typable_heap(qr_,qs):
    if qr_=='Imm_r':
        return qs in ['Imm','RO']
    else:
        return qs in ['Mut','RO']

# q_subtype closure
sub = set()
for a in q:
    if a!='Lost': sub.add((a,a))
for a in q: sub.add((a,'RO'))
for a in q: sub.add(('Bot',a))
changed=True
while changed:
    changed=False
    for (a,b) in list(sub):
        for (c,d) in list(sub):
            if b==c and (a,d) not in sub:
                sub.add((a,d)); changed=True

# Check READ lemma: qctx_typable_context qr q qctx -> qctx_typable_heap qr' (rec_fld qr mut) -> qctx_typable_context qr' (stype_fld_ro q mut) qctx
bad=[]
for qq in q:
  for qrr in qr:
    for mut in qf:
      for qc_ in qr:
        if not qctx_typable_context(qrr,qq,qc_): continue
        for qrv in qr:
          if not qctx_typable_heap(qrv, rec_fld(qrr,mut)): continue
          res = stype_fld_ro(qq,mut)
          if not qctx_typable_context(qrv,res,qc_):
            bad.append((qq,qrr,mut,qc_,qrv,res))
print("READ lemma counterexamples:", len(bad))
for b in bad[:40]: print(b)
EOF
python3 explore.py

cd /tmp/pico_explore && cat > explore2.py <<'EOF'
exec(open('explore.py').read().split('# Check READ')[0])

# WRITE lemma: qctx_typable_context qr_recv q_ty qctx
#   and qctx_typable_context qr_val q_valty qctx
#   and (q_valty, stype_fld_ro q_ty mut) in sub
#   -> qctx_typable_heap qr_val (rec_fld qr_recv mut)
bad=[]
for q_ty in q:
  for qr_recv in qr:
    for qctx in qr:
      if not qctx_typable_context(qr_recv,q_ty,qctx): continue
      for q_valty in q:
        for qr_val in qr:
          if not qctx_typable_context(qr_val,q_valty,qctx): continue
          for mut in qf:
            if (q_valty, stype_fld_ro(q_ty,mut)) not in sub: continue
            if not qctx_typable_heap(qr_val, rec_fld(qr_recv,mut)):
              bad.append((q_ty,qr_recv,qctx,q_valty,qr_val,mut,stype_fld_ro(q_ty,mut)))
print("WRITE lemma counterexamples:", len(bad))
for b in bad[:60]: print(b)
EOF
